\mathrm{df\text{-}metric\text{-}point}\vdash\;\begin{aligned}
\mathsf{Pt}_{\mathcal A}(x)&\leftrightarrow\mathsf{Met}(\mathcal A)\land\mathsf{Fun}(x,N,A)\land\forall i<j\;D_{x(i),x(j)}\le_R\widehat{\varepsilon_i},\\
x=_{\mathcal A}y&\leftrightarrow\mathsf{Pt}_{\mathcal A}(x)\land\mathsf{Pt}_{\mathcal A}(y)\land\forall k\;D_{x(k),y(k)}\le_R\widehat{2\varepsilon_k},\\
\widehat a_{\mathcal A}&\coloneqq\{\langle k,b\rangle_N:k\in N\land b=a\}\qquad(a\in A),\\
x\in\widehat{\mathcal A}&\;:\!\Longleftrightarrow\;\mathsf{Pt}_{\mathcal A}(x).
\end{aligned}
